// Pseudo: enforce tenant-scoped lookups and region routing
function routeQuery(req) {
  const { tenantId, region } = req;
  const policyVersion = getCurrentPolicyVersion(tenantId);
  const vectorStore = getTenantVectorStore(`${tenantId}_${region}`);

  if (!isCompliantWithPolicy(req, policyVersion)) {
    throw new PolicyViolationError();
  }

  return vectorStore.search(req.query, {
    tenantId,
    policyVersion,
    dataMinimization: true
  });
}
```

## Why This Is Asked

A practical exercise to gauge understanding of rate limiting, multi-tenant isolation, and backpressure in an LLM gateway.

## Key Concepts

- Token-bucket rate limiting
- Per-tenant quotas
- Backpressure and fairness
- Observability and tracing

## Code Example

```javascript
// Pseudo: simple token bucket for a tenant
class Bucket {
  constructor(capacity, refillPerMs) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillPerMs = refillPerMs;
    this.last = Date.now();
  }
  take(n = 1) {
    const now = Date.now();
    const elapsed = now - this.last;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerMs);
    this.last = now;
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }
}
```

